n("צורי", "צורי פירושו הסלע שלי, והשם בנוי על המילה צור עם סיומת של שייכות. צור הוא סלע קשה, ובעברית העתיקה המילה מתארת גם מקום מבטחים, מחסה שאפשר להישען עליו. מאותה מילה נבנו גם צור וצוריאל.", ["צור", "צוריאל"])
n("שמריהו", "שמריהו מחבר את הפועל שמר עם יהו, צורה של שם ה׳, ופירושו ה׳ שומר עליי. יהו בסוף השם היא צורה ארוכה של הסיומת יה, כמו בישעיהו ובבניהו. מאותו שורש, ש־מ־ר, באות גם המילים שמירה, משמר ושומר.")
n("אוליביה", "אוליביה הוא שם שמקובל לקשר למילה הלטינית אוליבה, זית. הזית הוא עץ ותיק בארץ, שגדל בהרים ובשפלה וחי מאות שנים, ומהפרי שלו מפיקים שמן. השם עבר לשפות רבות באירופה, וגם אוליבר הוא שם שמקובל לקשר לעץ הזית.")
n("איידל", "איידל היא מילה ביידיש שפירושה עדינה ומעודנת. המילה באה מהמילה הגרמנית אדל, אצילי, והשתנתה בדרך ליידיש. השם היה מוכר בקהילות אשכנז, ואידל הוא כתיב אחר של אותו שם.", ["אידל"])
n("אכרם", "אכרם היא צורת היתרון של המילה הערבית כרים, נדיב, כלומר מי שנדיב יותר מכולם. היא באה מהשורש כ־ר־מ, שעניינו נדיבות וכבוד, ומאותו שורש באים בערבית גם כרים וכרם. בעברית אותן אותיות, כרם, הן שדה של גפנים.")
n("חן", "חן הוא יופי נעים, מה שגורם לאדם או לדבר למצוא חן בעיני מי שרואה אותו. בתורה נאמר על נח שמצא חן בעיני ה׳, והצירוף למצוא חן מוכר בעברית עד היום. מאותו שורש, ח־נ־נ, באות גם המילים חנינה ותחנונים. השם ניתן לבנים ולבנות.")
n("ליעם", "ליעם מחבר את המילים לי ועם, ופירושו יש לי עם, קהל שאפשר להיות חלק ממנו. באותה דרך נבנו שמות עבריים רבים שמתחילים ב־לי, כמו ליאור וליעד. בעברית אפשר לשמוע בו דמיון לשם ליאם, אבל המקור של ליאם אחר.")
n("נוי", "נוי הוא יופי וקישוט, והמילה מוכרת בעברית בצירופים כמו גינת נוי ועצי נוי, צמחים שנוטעים בשביל היופי שלהם. בלשון חכמים מוכר הצירוף נוי סוכה, הקישוטים שתולים בסוכה. מאותה מילה נבנו גם נויה, נוייה ולינוי.", ["נויה", "נוייה"])
n("סמיר", "סמיר היא מילה ערבית למי שמשתתף בשיחות ערב, חבר שאפשר לשבת איתו ולדבר עד שעה מאוחרת. היא באה מהשורש ס־מ־ר, ומאותו שורש באה בערבית המילה סמר, שיחת ערב בין חברים. סמירה היא הצורה של השם בלשון נקבה.", ["סמירה"])
n("סמר", "סמר היא מילה ערבית לשיחה של חברים בשעות הערב, אחרי שהיום נגמר. בערבית המילה קשורה לשעות הלילה, שבהן נהגו לשבת יחד, לספר סיפורים ולשוחח. מאותו שורש, ס־מ־ר, באים בערבית גם סמיר וסמירה. השם ניתן לבנים ולבנות.")
n("עלאא", "עלאא היא מילה ערבית שפירושה רוממות ומעלה, מקום גבוה או מעמד נעלה. היא באה מהשורש ע־ל־ו, שקיים גם בעברית, ומאותו שורש באות בעברית המילים עלייה, עליון ומעלה. בערבית המילה משמשת גם לתיאור של כבוד וגדולה.")
n("ראשית", "ראשית היא התחלה, הנקודה שבה דבר מתחיל. המילה הראשונה בתורה היא בראשית, ועל שמה נקרא גם החומש הראשון. ראשית היא גם החלק הראשון של היבול, כמו ראשית הקציר שהביאו לבית המקדש. מאותו שורש באות גם המילים ראש וראשון.")
n("איתיאל", "איתיאל מחבר את המילה איתי עם אל, ופירושו אלוהים איתי. בספר משלי איתיאל הוא מי שאליו מופנים דברי החכמה של אגור בן יקה. מאותה מילה נבנה גם השם איתי, שפירושו מי שנמצא איתי.", ["איתי"])
n("אנה", "אנה היא הצורה של השם חנה בשפות רבות באירופה, והיא עברה אליהן דרך היוונית והלטינית. חנה בעברית היא מלשון חן וחסד, ובשפות האחרות צליל הח׳ נשמט. אן היא הצורה הצרפתית והאנגלית של אותו שם.", ["חנה", "אן"])
n("נדא", "נדא היא המילה הערבית לטל, הטיפות הקטנות שמופיעות על העשב ועל העלים בשעות הבוקר המוקדמות. בקיץ של הארץ, כשאין גשם, הטל הוא מקור חשוב של לחות לצמחים. בעברית הפירוש שלו קרוב לשם טל.")
n("פואד", "פואד היא מילה ערבית ללב, ובמיוחד ללב כמקום של רגש ושל מחשבה. בשירה הערבית המילה מופיעה פעמים רבות בתיאורים של אהבה ושל געגועים. השם מוכר בערבית שנים רבות, ובעברית הוא נכתב בארבע אותיות.")
n("אשירה", "אשירה פירושה אני אשיר, צורה של הפועל לשיר בגוף ראשון. בתורה שירת הים נפתחת במילה הזאת, השיר שבני ישראל שרו אחרי שעברו את ים סוף. מאותו שורש, ש־י־ר, באות גם המילים שיר, שירה ומשורר.")
n("בניהו", "בניהו מחבר את הפועל בנה עם יהו, צורה של שם ה׳, ופירושו ה׳ בנה. בספר שמואל בניהו בן יהוידע הוא אחד מגיבורי דוד, ואחר כך הוא שר הצבא של שלמה. בניה היא צורה קצרה של אותו שם, ומאותו שורש באות המילים בניין ובנייה.", ["בניה"])
n("ג'מיל", "ג'מיל היא מילה ערבית שפירושה יפה, ובערבית היא משמשת גם לטובה, מעשה טוב שעושים למישהו. היא באה מהשורש ג'־מ־ל, ומאותו שורש באה גם המילה ג'מאל, יופי. ג'מילה היא הצורה של השם בלשון נקבה.", ["ג'מילה"])
n("יוחנן", "יוחנן מחבר את יו, צורה של שם ה׳, עם הפועל חנן, ופירושו ה׳ חנן, נתן מתנה בחסד. בתנ״ך יש כמה אנשים בשם הזה, ובהם יוחנן בן קרח בימי ירמיהו. השם עבר לשפות רבות, ומכאן יאן ושון באירופה, ויחיא וחנא בערבית.", ["יחיא", "שון", "יאן", "חנא"])
n("יששכר", "יששכר הוא בנם של יעקב ולאה, ובתורה שמו קשור למילים יש שכר. על שמו נקרא שבט יששכר, שנחלתו הייתה בעמק יזרעאל ובגליל התחתון. מאותו שורש, ש־כ־ר, באות גם המילים שכר ומשכורת.")
n("נביל", "נביל היא מילה ערבית שפירושה אציל ונעלה, ובערבית היא מתארת גם דבר מכובד ובעל ערך. נבילה היא הצורה של השם בלשון נקבה. השם מוכר בערבית שנים רבות, ובעברית הוא נכתב בארבע אותיות.", ["נבילה"])
n("סלאמה", "סלאמה היא מילה ערבית שפירושה שלום וביטחון, מצב שבו אדם נשמר מכל רע. היא באה מהשורש ס־ל־מ, שהוא אותו שורש של המילה העברית שלום, ומאותו שורש באות בערבית גם המילים סלאם וסלים. בערבית אומרים מע אל־סלאמה כשנפרדים, ופירוש הברכה הוא שהדרך תעבור בשלום.")
n("עאמר", "עאמר היא מילה ערבית שפירושה מלא חיים, וגם מי שמיישב מקום ובונה בו. היא באה מהשורש ע־מ־ר, ומאותו שורש בא בערבית גם השם עמאר. בערבית מקום עאמר הוא מקום מיושב ופורח, ההפך ממקום שומם.")
n("רזאן", "רזאן היא מילה ערבית שפירושה רוגע ושיקול דעת, היכולת לחשוב בשקט לפני שפועלים. היא באה מהשורש ר־ז־נ, שעניינו כובד ויציבות, כמו דבר שאינו זז ממקומו. בעברית הפירוש שלו קרוב למילים יישוב הדעת ושלווה.")
n("אליאל", "אליאל מחבר את המילה אלי, אלוהיי, עם אל, ופירושו אלוהיי הוא האל. בשם יש פעמיים את המילה אל, פעם בתחילתו ופעם בסופו. באותה דרך נבנו שמות עבריים רבים, כמו אליה, שבו מתחברים אלי ויה, קיצור של שם ה׳.")
n("אלרום", "אלרום מחבר את המילים אל ורום, ופירושו אלוהים במרומים, במקום גבוה. רום הוא גובה, ומאותו שורש, ר־ו־מ, באות גם המילים רם, מרום והתרוממות. אלרום הוא גם שמו של קיבוץ בצפון רמת הגולן.")
n("כליל", "כליל הוא שלם, דבר שאין בו חסר, ובעברית הוא מוכר בצירוף כליל היופי. בעברית של היום אומרים גם שדבר נעלם כליל, כלומר לגמרי. כליל החורש הוא עץ בר שפורח בארץ בסוף החורף ובאביב בפרחים ורודים.")
n("לונה", "לונה היא המילה הלטינית לירח, ומאותה מילה באות בשפות אירופה מילים שקשורות לירח. באיטלקית ובשפה הספרדית לונה היא עד היום המילה הרגילה לירח. לונא היא כתיב אחר של אותו שם.", ["לונא"])
n("סידרא", "סידרא היא המילה הערבית לעץ השיזף, עץ בר קוצני שגדל בארץ באזורים חמים, כמו בקעת הירדן והערבה. הפירות שלו קטנים, עגולים ומתוקים, ואוכלים אותם טריים או מיובשים. סידרה הוא כתיב אחר של אותו שם.", ["סידרה"])
n("פהד", "פהד היא המילה הערבית לנמר ציד, חיה ממשפחת החתולים שידועה במהירות שלה. בעבר חי נמר הציד גם בארץ, בנגב ובערבה, אבל הוא נעלם מכאן לפני שנים רבות. בעברית הוא נקרא גם ברדלס.")
n("שאול", "שאול פירושו מי שנתבקש, מי שביקשו אותו. בספר שמואל שאול בן קיש, משבט בנימין, נמשח למלך הראשון של ישראל. מאותו שורש, ש־א־ל, באות גם המילים שאלה ושאילה.")
n("תיאו", "תיאו הוא שם שבנוי על המילה היוונית תאוס, אל, ומקובל לראות בו קיצור של שמות יווניים ארוכים כמו תיאודור, מתנת האל. מאותה מילה יוונית באות גם מילים רבות בשפות אירופה. תאו הוא כתיב אחר של אותו שם.", ["תאו"])
n("אביר", "אביר הוא חזק ואמיץ, ובעברית העתיקה המילה מתארת עוצמה וגבורה. בברכת יעקב לבניו אלוהים נקרא אביר יעקב, החזק של יעקב. בעברית של היום אביר הוא גם לוחם רכוב על סוס מימי הביניים, ומכאן המילה אבירות.")
n("אליס", "אליס הוא שם אירופי עתיק, שמקורו בשם הגרמני אדלהייד, שבנוי על המילה אדל, אצילי. השם עבר מצרפתית לאנגלית, ומשם לשפות רבות. בעברית הוא נשמע קרוב לשם אליסה, אבל מקורו של אליסה אחר.")
n("ארד", "ארד הוא כתיב אחר של ערד, העיר שבצפון מזרח הנגב, בין באר שבע לים המלח. ליד העיר נמצא תל ערד, ובו נחשפו שרידים של עיר כנענית ושל מצודה מימי המלוכה. בעברית של היום ארד היא גם המילה לסגסוגת של נחושת ובדיל.")
n("הודא", "הודא היא מילה ערבית שפירושה הדרכה בדרך הנכונה, כמו אור שמראה את הדרך. היא באה מהשורש ה־ד־י, שעניינו הדרכה, ומאותו שורש בא גם השם מהדי, מי שהודרך. השם מוכר בערבית שנים רבות, ובעברית הוא נכתב בארבע אותיות.")
n("וסים", "וסים היא מילה ערבית שפירושה נאה ויפה פנים. היא באה מהשורש ו־ס־מ, שעניינו סימן, ובערבית המילה וסם היא סימן או חותם, תו שמבדיל דבר אחד מאחר. בעברית הפירוש שלו קרוב למילה נאה.")
n("חגי", "חגי בנוי על המילה חג, יום של שמחה ושל חגיגה. חגי הוא אחד מתרי עשר הנביאים, וספר קצר בתנ״ך נקרא על שמו. הוא פעל בירושלים אחרי שיבת ציון, בימים שבהם נבנה בית המקדש השני. מאותה מילה נבנה גם השם חגית.", ["חגית"])
n("נאוה", "נאוה היא יפה, נעימה למראה. בשיר השירים המילה מתארת את הרעיה, ובעברית העתיקה היא מתארת גם דבר מתאים והולם. מאותו שורש באה גם המילה נאה, ומאותה מילה נבנה גם השם נאיה.", ["נאיה"])
n("רזיאל", "רזיאל מחבר את המילה רזי, הסוד שלי, עם אל, ופירושו הסוד של אלוהים. רז היא מילה שבאה מהפרסית ומוכרת כבר בארמית העתיקה, ומאותה מילה באה גם המילה רזים, סודות. מאותה מילה נבנו גם רז ואלירז.", ["רז"])
n("תכלת", "תכלת היא צבע כחול בהיר, כמו צבע השמים ביום בהיר. בתורה פתיל של תכלת נקשר לציציות שבכנפות הבגד, ובימי קדם הפיקו את הצבע מחלזון ים. בעברית של היום הצירוף תכלת לבן מתאר את צבעי הדגל.")
n("חוסאם", "חוסאם היא מילה ערבית לחרב, ובמיוחד לחרב חדה שחותכת היטב. היא באה מהשורש ח־ס־מ, שעניינו חיתוך והכרעה, ובערבית המילה חסם היא הכרעה ברורה. לחרב יש בערבית כינויים רבים, וחוסאם הוא אחד מהם.")
n("חנוך", "חנוך הוא מלשון חינוך, וגם מלשון חנוכה, הקדשה של דבר חדש. בספר בראשית חנוך הוא אחד הדורות שבין אדם לנח, והוא מתואר כמי שהלך בדרכי האלוהים. מאותו שורש, ח־נ־כ, באות גם המילים חניך ומחנך.")
n("לונא", "לונא היא כתיב אחר של השם לונה, המילה הלטינית לירח. בכתיב הזה הה׳ בסוף מתחלפת באל״ף, כמו בעוד שמות שהגיעו לעברית משפות אחרות. באיטלקית לונה היא עד היום המילה הרגילה לירח.", ["לונה"])
n("שחרי", "שחרי פירושו השחר שלי, והשם בנוי על המילה שחר עם סיומת של שייכות. שחר הוא האור הראשון של הבוקר, לפני שהשמש עולה. מאותה מילה באה גם המילה שחרית, שעות הבוקר המוקדמות, ומאותה מילה נבנה גם השם שחר.", ["שחר"])
n("ג'וליא", "ג'וליא היא צורה של השם הרומי יוליה, הצורה של השם יוליוס בלשון נקבה. בערבית השם נכתב כך, עם אל״ף בסוף, ובאנגלית ובאיטלקית הוא נשמע כמו ג'וליה. ג'ולי היא הצורה הצרפתית של אותו שם.", ["ג'וליה", "ג'ולי"])
n("חגית", "חגית בנויה על המילה חג, עם הסיומת ית של לשון נקבה. בספר שמואל חגית היא אחת מנשות דוד, ואמו של אדוניה. מאותו שורש, ח־ג־ג, באות גם המילים חגיגה וחגיגי, ומאותה מילה נבנה גם השם חגי.", ["חגי"])
n("מאג'ד", "מאג'ד היא מילה ערבית שפירושה מפואר ומכובד, מי שיש לו שם טוב. היא באה מהשורש מ־ג'־ד, ומאותו שורש באה גם המילה מג'ד, תהילה וכבוד. מאג'דה היא הצורה של השם בלשון נקבה.", ["מאג'דה"])
n("מהדי", "מהדי היא מילה ערבית שפירושה מי שהודרך בדרך הנכונה, כמו מי שמצא את השביל. היא באה מהשורש ה־ד־י, שעניינו הדרכה, ומאותו שורש בא גם השם הודא. השם מוכר בערבית שנים רבות, ובעברית הוא נכתב בארבע אותיות.")
n("מעוז", "מעוז הוא מבצר, מקום חזק ומוגן שאפשר למצוא בו מחסה. בספר תהילים המילה מתארת את ה׳ כמעוז, מקום מבטחים. המילה קרובה למילה עוז, חוזק, ובעברית מוכר גם הפיוט מעוז צור, ששרים בחנוכה.")
n("נדין", "נדין הוא שם צרפתי, צורת חיבה של השם הרוסי נדז'דה, שפירושו תקווה. השם עבר מרוסית לצרפתית, ומשם לשפות נוספות. נדיה היא צורת חיבה רוסית של אותו שם.", ["נדיה"])
n("קשת", "קשת היא קשת בענן, פס של צבעים שמופיע בשמים כשהשמש מאירה אחרי גשם. בסיפור המבול הקשת בענן היא אות לברית בין אלוהים לבין הארץ. בעברית קשת היא גם כלי שיורים בו חצים, וגם קו מעוגל, כמו קשת של גשר.")
n("ראיד", "ראיד היא מילה ערבית לחלוץ, מי שהולך ראשון ומוביל את האחרים. בערבית העתיקה המילה תיארה את מי שנשלח לפני השיירה לחפש מקום עם מים ומרעה. רואד היא הצורה של המילה ברבים, וגם היא משמשת כשם.")
n("שאדי", "שאדי היא מילה ערבית למי ששר ומזמר. היא באה מהשורש ש־ד־ו, שעניינו שירה וזמרה. השם מוכר בערבית שנים רבות, ובעברית הפירוש שלו קרוב לשמות שבנויים על המילה שיר, כמו שירה ושיר.")
n("שגיא", "שגיא הוא גדול ונישא, מילה שמתארת גודל ועוצמה. בספר איוב המילה מתארת את אלוהים כגדול יותר ממה שאדם יכול להבין. בארמית שגיא פירושו הרבה, והמילה מוכרת גם מהתלמוד.")
n("אביחי", "אביחי מחבר את המילים אבי וחי, ופירושו אבי חי, האב שלי חי וקיים. באותה דרך נבנו שמות עבריים רבים שמתחילים ב־אבי, כמו אביאל ואבינועם. מאותו שורש, ח־י־ה, באות גם המילים חיים וחיות.")
n("אבינועם", "אבינועם מחבר את המילים אבי ונועם, ופירושו אבי הוא נעים. בספר שופטים אבינועם הוא אביו של ברק, המצביא שיצא עם דבורה הנביאה למלחמה. נועם היא נעימות ועדינות, ומאותו שורש באה גם המילה נעים.")
n("דקל", "דקל הוא עץ התמר, עץ גבוה עם גזע ישר וכתר של עלים ארוכים בראשו. בעברית העתיקה העץ נקרא תמר, והמילה דקל באה מלשון חכמים. בארץ גדלים מטעים גדולים של תמרים בבקעת הירדן, בערבה ובעמק בית שאן. השם ניתן לבנים ולבנות.")
n("ישעיהו", "ישעיהו מחבר את המילה ישע, ישועה, עם יהו, צורה של שם ה׳, ופירושו ה׳ הוא ישועה. ישעיהו בן אמוץ הוא נביא שפעל בירושלים בימי מלכי יהודה, וספר ארוך בתנ״ך נקרא על שמו. ישעיה היא צורה קצרה של אותו שם.", ["ישעיה"])
n("מאסא", "מאסא היא המילה הערבית ליהלום, אבן חן שקופה, מבריקה וקשה מאוד. יהלום נוצר מפחמן עמוק באדמה, בלחץ ובחום גבוהים, ומשם הוא מגיע אל פני השטח. מאסה הוא כתיב אחר של אותו שם.", ["מאסה"])
n("מיתר", "מיתר הוא החוט המתוח שמפיק צליל בכלי נגינה, כמו בגיטרה, בכינור ובנבל. כשפורטים על המיתר הוא רוטט, וככל שהוא קצר ומתוח יותר הצליל גבוה יותר. מיתר הוא גם שמו של יישוב בנגב, ליד באר שבע.")
n("נאדר", "נאדר היא מילה ערבית שפירושה נדיר, דבר שאין הרבה כמוהו. היא באה מהשורש נ־ד־ר, ומאותו שורש באה בערבית גם המילה נאדרה, דבר נדיר. נאדרה היא גם הצורה של השם בלשון נקבה.", ["נאדרה"])
